// Toolbar icon toggle. No default_popup in the manifest, so clicking the icon
// fires onClicked directly. State is one boolean in chrome.storage.local; the
// content script watches it via storage.onChanged, so no message passing and no
// tab reload is needed.

const DEFAULT_ENABLED = true;

async function isEnabled() {
  const { enabled } = await chrome.storage.local.get('enabled');
  return enabled === undefined ? DEFAULT_ENABLED : enabled;
}

// Generated by tools/make-icons.py — re-run it after editing the colours there.
const ICON = (state) => ({
  16: `icons/${state}-16.png`,
  32: `icons/${state}-32.png`,
  48: `icons/${state}-48.png`,
  128: `icons/${state}-128.png`
});

// State is carried by the icon itself: blue when on, grey when off.
async function paint(enabled) {
  await chrome.action.setIcon({ path: ICON(enabled ? 'active' : 'inactive') });
  await chrome.action.setTitle({
    title: enabled
      ? 'LinkedIn Hide: on — click to disable'
      : 'LinkedIn Hide: off — click to enable'
  });
}

// MV3 service workers are torn down when idle, so repaint on every wake-up.
chrome.runtime.onInstalled.addListener(async () => paint(await isEnabled()));
chrome.runtime.onStartup.addListener(async () => paint(await isEnabled()));

chrome.action.onClicked.addListener(async () => {
  const next = !(await isEnabled());
  await chrome.storage.local.set({ enabled: next });
  await paint(next);
});
